import { Lightbulb } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Card, CardTitle } from "@/components/ui/card";
import type { Finding } from "@/lib/contracts";
import { ruleTitle } from "@/lib/rule-catalog";

/** Rule-based explanation built only from finding fields. Not generated by an LLM and not a legal conclusion. */
export function WhyPanel({ finding }: { finding: Finding }) {
  return (
    <Card variant="glass" className="space-y-3" data-testid="why-panel">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <CardTitle className="flex items-center gap-2 text-base"><Lightbulb className="size-4 text-brand-bright" aria-hidden /> Why was this flagged?</CardTitle>
        <Badge variant="neutral">Rule-based explanation</Badge>
      </div>
      <p className="text-sm leading-relaxed">{finding.explanation}</p>
      <div className="space-y-1.5 text-sm">
        <p className="font-mono text-[11px] uppercase tracking-wider text-muted">Rules that fired · {finding.rule_version}</p>
        {finding.rule_ids.length ? (
          <ul className="flex flex-wrap gap-2">
            {finding.rule_ids.map((r) => <li key={r}><Badge variant="neutral" title={r}>{ruleTitle(r)}</Badge></li>)}
          </ul>
        ) : (
          <p className="text-muted">No deterministic rule fired — flagged by the statistical outlier model only.</p>
        )}
      </div>
      <div className="text-sm">
        <p className="font-mono text-[11px] uppercase tracking-wider text-muted">Detected by</p>
        <p className="mt-1">
          {finding.detected_by.includes("rule") ? "Rule check" : null}
          {finding.detected_by.length > 1 ? " + " : null}
          {finding.detected_by.includes("ml_outlier") ? "Outlier model" : null}
        </p>
        {finding.model_score != null ? (
          <p className="mt-1 text-muted">
            Outlier score <span className="num text-fg">{finding.model_score.toFixed(3)}</span>
            {finding.model_threshold != null && <> vs threshold <span className="num text-fg">{finding.model_threshold.toFixed(3)}</span></>} ({finding.model_version}). This is an unusualness score, <strong>not</strong> a probability of non-compliance.
          </p>
        ) : finding.detected_by.includes("ml_outlier") ? (
          <p className="mt-1 text-muted">Outlier score not computed for this fixture.</p>
        ) : null}
      </div>
    </Card>
  );
}
